/* ViewImage-compatible local lightbox. Based on ViewImage.js 2.0.2 (MIT). */
(() => {
  const ViewImage = {
    target: "[view-image] img",
    init(target) {
      if (target) this.target = target
      // Capture the click before Quartz SPA/navigation handlers can consume it.
      document.removeEventListener("click", this.listener, true)
      document.addEventListener("click", this.listener, true)
    },
    listener(event) {
      if (event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return
      const selector = ViewImage.target
        .split(",")
        .map((item) => `${item.trim()}:not([no-view]):not([data-no-lightbox]):not([atk-emoticon]):not(.comments-emoticon)`)
        .join(",")
      if (!(event.target instanceof Element)) return
      const image = event.target.closest(selector)
      if (!image) return
      const scope = image.closest("[view-image]") || document.body
      const images = [...scope.querySelectorAll(selector)].map((item) => item.href || item.src)
      event.preventDefault()
      event.stopPropagation()
      ViewImage.display(images, image.href || image.src)
    },
    display(images, current) {
      let index = Math.max(0, images.indexOf(current))
      const overlay = document.createElement("dialog")
      overlay.className = "view-image"
      overlay.setAttribute("aria-label","图片预览")
      overlay.tabIndex=-1
      overlay.innerHTML = `
        <style>
          .view-image{position:fixed;inset:0;z-index:500;padding:1rem;margin:0;box-sizing:border-box;width:100dvw;height:100dvh;max-width:none;max-height:none;border:0;background:transparent;overscroll-behavior:contain;touch-action:none;display:flex;flex-direction:column;animation:view-image-in 300ms;backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px)}
          .view-image::backdrop{background:transparent}.view-image__out{animation:view-image-out 300ms forwards}@keyframes view-image-in{from{opacity:0}}@keyframes view-image-out{to{opacity:0}}
          .view-image-close__full{position:absolute;inset:0;background:rgba(48,55,66,.3);cursor:zoom-out}.view-image-container{height:0;flex:1;display:flex;align-items:center;justify-content:center}.view-image-lead{display:contents}.view-image-lead img{position:relative;z-index:1;max-width:100%;max-height:100%;object-fit:contain;border-radius:3px;animation:view-image-lead-in 300ms}@keyframes view-image-lead-in{from{opacity:0;transform:translateY(-20px)}}
          .view-image-tools{position:absolute;bottom:5%;left:1rem;right:1rem;z-index:1;display:flex;justify-content:space-between;align-content:center;max-width:600px;margin:0 auto;padding:10px;border-radius:5px;background:rgba(0,0,0,.1);backdrop-filter:blur(10px);color:#fff}.view-image-btn{width:32px;height:32px;display:flex;justify-content:center;align-items:center;cursor:pointer;border:0;border-radius:3px;background-color:rgba(255,255,255,.2);padding:0}.view-image-btn:hover{background-color:rgba(255,255,255,.5)}.view-image-tools__count{width:60px;display:flex;align-items:center;justify-content:center}.view-image-tools__flip{display:flex;gap:10px}.view-image-tools [class*=-close]{margin:0 10px}
        </style>
        <div class="view-image-container"><div class="view-image-lead"></div><div class="view-image-close view-image-close__full"></div></div>
        <div class="view-image-tools"><div class="view-image-tools__count"><span><b class="view-image-index"></b>/${images.length}</span></div><div class="view-image-tools__flip"><button class="view-image-btn view-image-tools__flip-prev" aria-label="上一张"><svg width="20" height="20" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M31 36L19 24L31 12" stroke="white" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></button><button class="view-image-btn view-image-tools__flip-next" aria-label="下一张"><svg width="20" height="20" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M19 12L31 24L19 36" stroke="white" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div><button class="view-image-btn view-image-close" aria-label="关闭"><svg width="16" height="16" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M8 8L40 40M8 40L40 8" stroke="white" stroke-width="4" stroke-linecap="round"/></svg></button></div>`
      const lead = overlay.querySelector(".view-image-lead")
      const setImage = () => {
        lead.innerHTML = ""
        const image = new Image()
        image.src = images[index]
        image.alt = "ViewImage"
        image.setAttribute("no-view", "")
        lead.append(image)
        overlay.querySelector(".view-image-index").textContent = index + 1
      }
      let closing = false,removed=false
      const remove=()=>{
        if(removed)return
        removed=true
        document.removeEventListener("keydown",keyboard)
        if(overlay.open)overlay.close()
        overlay.remove()
        document.dispatchEvent(new CustomEvent("view-image-close",{detail:{overlay}}))
      }
      const close = () => {
        if (closing) return
        closing = true
        document.removeEventListener("keydown", keyboard)
        // Retain modal interaction blocking through the closing animation.
        overlay.classList.add("view-image__out")
        const fallback = window.setTimeout(remove, 400)
        overlay.addEventListener("animationend", event => {
          if (event.target !== overlay) return
          window.clearTimeout(fallback)
          remove()
        })
      }
      const keyboard = (event) => {
        if (event.key === "Escape") close()
        if (event.key === "ArrowLeft") { index = (index + images.length - 1) % images.length; setImage() }
        if (event.key === "ArrowRight") { index = (index + 1) % images.length; setImage() }
      }
      overlay.addEventListener("click", (event) => {
        event.stopPropagation()
        if(closing)return
        if (event.target.closest(".view-image-close")) close()
        if (event.target.closest(".view-image-tools__flip-prev")) { index = (index + images.length - 1) % images.length; setImage() }
        if (event.target.closest(".view-image-tools__flip-next")) { index = (index + 1) % images.length; setImage() }
      })
      overlay.addEventListener("cancel",event=>{event.preventDefault();close()})
      overlay.addEventListener("close",remove,{once:true})
      document.body.append(overlay)
      overlay.showModal()
      overlay.focus({preventScroll:true})
      document.dispatchEvent(new CustomEvent("view-image-open",{detail:{overlay}}))
      document.addEventListener("keydown", keyboard)
      setImage()
    },
  }
  window.ViewImage = ViewImage
})()
